527:      * @param effects a LinkedList of estimated causal effects
528:      * @param trueEffect the true causal effect to compute the distance to
529:      * @return the minimum distance between the true causal effect and the set of estimated effects
530:      */
531:     public double distance(LinkedList<Double> effects, double trueEffect) {
532:         effects = new LinkedList<>(effects);
533:         if (effects.isEmpty()) return trueEffect;
534:         if (effects.size() == 1) return abs(effects.get(0) - trueEffect);
535:         Collections.sort(effects);
536:         double minv = effects.getFirst();
537:         double maxv = effects.getLast();
538:         if (trueEffect >= minv && trueEffect <= maxv) return 0.0;
539:         return min(abs(trueEffect - minv), abs(trueEffect - maxv));
540:     }
